import React from "react";

export default function Header({ profile, socialLinks }) {
  return (
    <header className="mb-12">
      <div className="grid grid-cols-1 items-start gap-8 sm:grid-cols-[190px_minmax(0,1fr)]">
        <div>
          <img
            src={profile.photo}
            alt={profile.name}
            className="w-full max-w-[190px] rounded-2xl object-cover"
          />
        </div>

        <div>
          <h1 className="text-[3.25rem] font-semibold leading-none tracking-[-0.03em] text-zinc-900">
            {profile.name}
          </h1>

          <div className="mt-4 max-w-2xl text-[1.08rem] leading-8 text-zinc-700">
            {profile.description}
          </div>

          <div className="mt-4 flex flex-wrap items-center gap-x-3 gap-y-2 text-[1rem] text-zinc-600">
            {socialLinks.map((link, index) => (
              <React.Fragment key={link.label}>
                <a
                  href={link.href}
                  target="_blank"
                  rel="noopener noreferrer"
                  className="underline underline-offset-2 transition-colors hover:text-zinc-900"
                >
                  {link.label}
                </a>
                {index < socialLinks.length - 1 && (
                  <span className="text-zinc-400">/</span>
                )}
              </React.Fragment>
            ))}
          </div>
        </div>
      </div>
    </header>
  );
}
